<?php
require_once __DIR__ . '/../db.php';$data=json_input();$plan=$data['plan']??'';$plans=['single'=>50000,'pro_monthly'=>250000,'pro_annual'=>2500000];if(!isset($plans[$plan]))json_out(['ok'=>false,'message'=>'Unknown plan'],422);$cfg=require __DIR__.'/../config.php';$secret=$cfg['payment']['secret_key'];if(!$secret)json_out(['ok'=>false,'message'=>'Payment credentials are not configured yet. Add CLYP_PAYSTACK_SECRET to the environment.'],503);
$uid=session_user_id();if(!$uid)json_out(['ok'=>false,'message'=>'Please log in before checkout.'],401);try{$q=db()->prepare('SELECT email FROM users WHERE id=?');$q->execute([$uid]);$email=$q->fetchColumn();if(!$email)json_out(['ok'=>false,'message'=>'User not found'],404);$payload=json_encode(['email'=>$email,'amount'=>$plans[$plan],'currency'=>'NGN','metadata'=>['user_id'=>$uid,'plan'=>$plan]]);$ch=curl_init('https://api.paystack.co/transaction/initialize');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$payload,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$secret,'Content-Type: application/json'],CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$res=json_decode($raw,true);if($code>=200&&$code<300&&!empty($res['data']['authorization_url']))json_out(['ok'=>true,'checkout_url'=>$res['data']['authorization_url']]);json_out(['ok'=>false,'message'=>'Could not initialize checkout'],502);}catch(Throwable $e){json_out(['ok'=>false,'message'=>'Checkout unavailable'],503);}
